package app.gtdial.lab;
import org.json.JSONObject;
import org.json.JSONArray;
import java.util.HashMap;
import java.util.Map;
import java.util.function.BiConsumer;

/** Prepare and acceptance re-read exactly the selected sources. No asynchronous result mutates diaries. */
final class AnalysisController {
    private final ExpansionStore store;private final ActivityHistoryStore activityStore;private final OpenRouterClient client;
    private final java.util.concurrent.atomic.AtomicInteger generation=new java.util.concurrent.atomic.AtomicInteger();private volatile boolean destroyed;
    AnalysisController(ExpansionStore store,ActivityHistoryStore activityStore,OpenRouterClient client){this.store=store;this.activityStore=activityStore;this.client=client;store.onAnalysisSourceDeleted(this::cancel);}
    void prepare(AnalysisSnapshot.Selection selection,BiConsumer<AnalysisSnapshot,String> done){cancel();int expected=generation.get();store.submit(()->AnalysisSnapshot.prepare(selection,AnalysisSnapshot.capture(store,activityStore,selection)),(snapshot,error)->{if(destroyed||generation.get()!=expected)return;done.accept(snapshot,error);});}
    void send(AnalysisSnapshot snapshot,String model,BiConsumer<JSONObject,String> done){cancel();int expected=generation.get();long credentialRevision=client.credentials.revision();JSONObject body;try{body=client.body(model,false,snapshot.payload(),null,AnalysisResponseValidator.schema());}catch(RuntimeException e){done.accept(null,safe(e));return;}store.submit(()->snapshot.sourceRevisionHash.equals(AnalysisSnapshot.capture(store,activityStore,snapshot.selection()).hash),(fresh,error)->{if(destroyed||expected!=generation.get()||credentialRevision!=client.credentials.revision())return;if(!error.isEmpty()||!Boolean.TRUE.equals(fresh)){done.accept(null,"SOURCE_CHANGED");return;}client.complete(body,false,(response,networkError)->{if(destroyed||expected!=generation.get()||credentialRevision!=client.credentials.revision())return;if(!networkError.isEmpty()){done.accept(null,networkError);return;}store.submit(()->{if(expected!=generation.get()||credentialRevision!=client.credentials.revision())throw new IllegalStateException("REQUEST_CANCELED");AnalysisSnapshot.Source now=AnalysisSnapshot.capture(store,activityStore,snapshot.selection());if(!snapshot.sourceRevisionHash.equals(now.hash))throw new IllegalStateException("SOURCE_CHANGED");JSONObject validated=AnalysisResponseValidator.validate(response,snapshot);JSONObject report=NutritionModels.object("schemaVersion",1,"id",NutritionModels.uuid(),"createdAt",System.currentTimeMillis(),"modelId",model,"rulesVersion",1,"requestedDomains",new JSONArray(snapshot.selection().domains),"snapshot",snapshot.localJson(),"response",validated);store.transaction(()->{if(expected!=generation.get()||credentialRevision!=client.credentials.revision())throw new IllegalStateException("REQUEST_CANCELED");store.saveAnalysisReport(report);});return report;},(report,storageError)->{if(destroyed||expected!=generation.get()||credentialRevision!=client.credentials.revision())return;done.accept(report,storageError);});});});}
    static final class HistoryPage {final java.util.List<JSONObject> reports;final JSONObject selected;final int total,page;HistoryPage(java.util.List<JSONObject> reports,JSONObject selected,int total,int page){this.reports=reports;this.selected=selected;this.total=total;this.page=page;}}
    void history(int page,String selectedId,BiConsumer<HistoryPage,String> done){store.submit(()->{int total=store.analysisReportCount(),actual=Math.min(page,Math.max(0,(total-1)/150));java.util.List<JSONObject> reports=store.analysisReportsPage(actual);JSONObject selected=selectedId.isEmpty()?null:store.analysisReport(selectedId);Map<String,String> hashes=new HashMap<>();if(selected==null)for(JSONObject report:reports)markStale(report,hashes);else markStale(selected,hashes);return new HistoryPage(reports,selected,total,actual);},done);}
    private void markStale(JSONObject report,Map<String,String> hashes){JSONObject saved=report.optJSONObject("snapshot");boolean stale=true;if(saved!=null)try{AnalysisSnapshot.Selection selected=AnalysisSnapshot.Selection.parse(saved.optJSONObject("selection"));String key=NutritionModels.canonical(selected.json()),hash=hashes.get(key);if(hash==null){hash=AnalysisSnapshot.capture(store,activityStore,selected).hash;hashes.put(key,hash);}stale=!saved.optString("sourceRevisionHash").equals(hash);}catch(RuntimeException ignored){stale=true;}NutritionModels.put(report,"stale",stale);}
    void cancel(){generation.incrementAndGet();client.cancel();}
    void destroy(){destroyed=true;cancel();}
    static String safe(RuntimeException error){String code=error.getMessage();return code!=null&&code.matches("[A-Z_]{1,80}")?code:"LOCAL_VALIDATION_FAILED";}
}


